def parse_money(s: str) -> float | None:
    if not s or s.lower() in ('', 'n/a'):
        return None

    # Remove leading $ sign
    cleaned = s.lstrip('$')

    try:
        # Replace thousands separators (commas) with empty string and parse as float
        number_str = cleaned.replace(',', '')
        return float(number_str)
    except ValueError:
        return None
